    "slug": "gst-credit-notes-cancelled-order-refunds-sequential-invoice-numbering-india",
    "title": "GST Credit Notes, Cancelled Order Refunds & Sequential Invoice Numbering Rules in India",
    "date": "November 19, 2026",
    "category": "Operations",
    "readTime": "10 min read",
    "wordCount": 2034,
    "image": "images/post-gst-invoicing.jpg",
